const TEMPLATE_KIND_LABELS: Record<TemplateKind, string> = {
  tattoo: 'Tattoo',
  piercing: 'Piercing',
  pmu: 'PMU',
  touch_up: 'Touch-up',
  minor: 'Minor (under 18)',
  custom: 'Custom',
}

const RETENTION_YEARS_OPTIONS = [3, 5, 7, 10] as const

interface SavePayload {
  name: string
  kind: TemplateKind
  sections: ConsentSection[]
  retention_years: number
  is_default: boolean
  language: string
  required_for_booking: boolean
  requires_guardian: boolean
}

interface TemplateBuilderProps {
  /** When provided, we're editing an existing template */
  templateId?: string
  /** Pre-populated values for edit mode */
  initialValues?: Partial<SavePayload>
  /** Current submission count — used to detect immutability violation risk */
  submissionCount?: number
  /** Called after successful save — receives new/updated template id */
  onSave?: (id: string) => void
}

export function TemplateBuilder({
  templateId,
  initialValues,
  submissionCount = 0,
  onSave,
}: TemplateBuilderProps) {
  const [name, setName] = useState(initialValues?.name ?? '')
  const [kind, setKind] = useState<TemplateKind>(initialValues?.kind ?? 'tattoo')
  const [sections, setSections] = useState<ConsentSection[]>(initialValues?.sections ?? [])
  const [retentionYears, setRetentionYears] = useState<number>(
    initialValues?.retention_years ?? 7
  )
  const [isDefault, setIsDefault] = useState(initialValues?.is_default ?? false)
  const [language, setLanguage] = useState(initialValues?.language ?? 'en')
  const [requiredForBooking, setRequiredForBooking] = useState(
    initialValues?.required_for_booking ?? false
  )
  const [requiresGuardian, setRequiresGuardian] = useState(
    initialValues?.requires_guardian ?? false
  )
  const [showPreview, setShowPreview] = useState(false)

  // Immutability violation dialog
  const [immutabilityDialog, setImmutabilityDialog] = useState<{
    open: boolean
    newVersion: number
  }>({ open: false, newVersion: 0 })

  const [isPending, startTransition] = useTransition()

  const handleAddSection = useCallback((sectionKind: ConsentSectionKind) => {
    const factory = DEFAULT_SECTION_FOR_KIND[sectionKind]
    const newSection = factory()
    setSections((prev) => {
      const order = prev.length
      return [...prev, { ...newSection, order }]
    })
  }, [])

  const doSave = useCallback(
    async (forceNewVersion = false) => {
      if (!name.trim()) {
        toast.error('Template name is required')
        return
      }
      if (sections.length === 0) {
        toast.error('Add at least one section before saving')
        return
      }

      const payload: SavePayload = {
        name: name.trim(),
        kind,
        sections,
        retention_years: retentionYears,
        is_default: isDefault,
        language,
        required_for_booking: requiredForBooking,
        requires_guardian: requiresGuardian,
      }

      const url =
        templateId && !forceNewVersion
          ? `/api/consent-forms/templates/${templateId}`
          : '/api/consent-forms/templates'

      const method = templateId && !forceNewVersion ? 'PATCH' : 'POST'

      let res: Response
      try {
        res = await fetch(url, {
          method,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })
      } catch {
        toast.error('Network error — please try again')
        return
      }

      if (res.status === 409) {
        const body = (await res.json()) as { error: string; new_version?: number }
        if (body.error === 'immutability_violation' && body.new_version) {
          setImmutabilityDialog({ open: true, newVersion: body.new_version })
          return
        }
        toast.error(body.error === 'slug_conflict' ? 'A template with this name already exists' : 'Conflict — please refresh')
        return
      }

      if (!res.ok) {
        const body = (await res.json().catch(() => ({ error: 'Unknown error' }))) as { error?: string }
        toast.error(body.error ?? 'Failed to save template')
        return
      }

      const result = (await res.json()) as { id: string }
      toast.success(forceNewVersion ? 'New version published' : templateId ? 'Template saved' : 'Template created')
      onSave?.(result.id)
    },
    [
      name,
      kind,
      sections,
      retentionYears,
      isDefault,
      language,
      requiredForBooking,
      requiresGuardian,
      templateId,
      onSave,
    ]
  )

  const handleSave = useCallback(() => {
    startTransition(() => { void doSave(false) })
  }, [doSave])

  const handlePublishNewVersion = useCallback(() => {
    setImmutabilityDialog({ open: false, newVersion: 0 })
    startTransition(() => { void doSave(true) })
  }, [doSave])

  return (
    <div className="flex h-full flex-col overflow-hidden">
      {/* ── Top bar ─────────────────────────────────────────────── */}
      <div className="flex shrink-0 items-center gap-3 border-b border-border bg-card px-4 py-3">
        <div className="flex flex-1 items-center gap-3 min-w-0">
          <Input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Template name…"
            className="h-8 w-56 text-sm font-medium"
          />

          <Select value={kind} onValueChange={(v) => setKind(v as TemplateKind)}>
            <SelectTrigger className="h-8 w-36 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(Object.keys(TEMPLATE_KIND_LABELS) as TemplateKind[]).map((k) => (
                <SelectItem key={k} value={k} className="text-xs">
                  {TEMPLATE_KIND_LABELS[k]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          {/* Retention years */}
          <div className="flex items-center gap-1.5">
            <Label className="text-xs text-muted-foreground whitespace-nowrap">Retention</Label>
            <Select
              value={String(retentionYears)}
              onValueChange={(v) => setRetentionYears(Number(v))}
            >
              <SelectTrigger className="h-8 w-20 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {RETENTION_YEARS_OPTIONS.map((y) => (
                  <SelectItem key={y} value={String(y)} className="text-xs">
                    {y} yr
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Language */}
          <Select value={language} onValueChange={setLanguage}>
            <SelectTrigger className="h-8 w-20 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="en" className="text-xs">EN</SelectItem>
              <SelectItem value="de" className="text-xs">DE</SelectItem>
              <SelectItem value="fr" className="text-xs">FR</SelectItem>
              <SelectItem value="es" className="text-xs">ES</SelectItem>
              <SelectItem value="it" className="text-xs">IT</SelectItem>
              <SelectItem value="nl" className="text-xs">NL</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Toggles */}
        <div className="flex shrink-0 items-center gap-4">
          <div className="flex items-center gap-1.5">
            <Switch
              id="requires-guardian"
              checked={requiresGuardian}
              onCheckedChange={setRequiresGuardian}
              aria-label="Requires guardian"
            />
            <Label htmlFor="requires-guardian" className="text-xs cursor-pointer">
              Guardian
            </Label>
          </div>
          <div className="flex items-center gap-1.5">
            <Switch
              id="required-for-booking"
              checked={requiredForBooking}
              onCheckedChange={setRequiredForBooking}
              aria-label="Required for booking"
            />
            <Label htmlFor="required-for-booking" className="text-xs cursor-pointer">
              Req. booking
            </Label>
          </div>
          <div className="flex items-center gap-1.5">
            <Switch
              id="is-default"
              checked={isDefault}
              onCheckedChange={setIsDefault}
              aria-label="Set as default"
            />
            <Label htmlFor="is-default" className="text-xs cursor-pointer">
              Default
            </Label>
          </div>
        </div>

        {/* Actions */}
        <div className="flex shrink-0 items-center gap-2">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => setShowPreview((v) => !v)}
            className="h-8 gap-1.5 text-xs"
          >
            {showPreview ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
            {showPreview ? 'Builder' : 'Preview'}
          </Button>

          {submissionCount > 0 && templateId && (
            <span className="text-xs text-muted-foreground">
              {submissionCount} submissions
            </span>
          )}

          <Button
            type="button"
            size="sm"
            onClick={handleSave}
            disabled={isPending}
            className="h-8 gap-1.5 text-xs"
          >
            {isPending ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Save className="h-3.5 w-3.5" />
            )}
            {templateId ? 'Save' : 'Create'}
          </Button>
        </div>
      </div>

      {/* ── Body ─────────────────────────────────────────────────── */}
      {showPreview ? (
        <div className="flex-1 overflow-hidden">
          <TemplatePreview
            templateName={name || 'Untitled Form'}
            sections={sections}
            requiresGuardian={requiresGuardian}
          />
        </div>
      ) : (
        <div className="flex flex-1 min-h-0 overflow-hidden">
          {/* LEFT — palette + section list */}
          <div className="flex w-[340px] shrink-0 flex-col border-r border-border overflow-hidden">
            <ScrollArea className="flex-1">
              <div className="space-y-4 p-4">
                {/* Section list (when non-empty) */}
                {sections.length > 0 && (
                  <div className="space-y-2">
                    <p className="px-1 text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Sections ({sections.length})
                    </p>
                    <SectionList sections={sections} onChange={setSections} />
                  </div>
                )}

                {/* Palette */}
                <SectionPalette onAddSection={handleAddSection} />
              </div>
            </ScrollArea>
          </div>

          {/* RIGHT — live preview */}
          <div className="flex-1 min-w-0 bg-[var(--color-builder-preview-bg,hsl(var(--muted)/0.3))]">
            <TemplatePreview
              templateName={name || 'Untitled Form'}
              sections={sections}
              requiresGuardian={requiresGuardian}
            />
          </div>
        </div>
      )}

      {/* ── Immutability violation dialog ────────────────────────── */}
      <Dialog
        open={immutabilityDialog.open}
        onOpenChange={(open) => {
          if (!open) setImmutabilityDialog({ open: false, newVersion: 0 })
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-amber-500" />
              Publish as New Version?
            </DialogTitle>
            <DialogDescription>
              This template has existing submissions. Saving changes will publish it as{' '}
              <strong>version {immutabilityDialog.newVersion}</strong>. Existing submissions keep
              their snapshot — only new consent requests will use the updated template.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setImmutabilityDialog({ open: false, newVersion: 0 })}
            >
              Cancel
            </Button>
            <Button onClick={handlePublishNewVersion} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Publish v{immutabilityDialog.newVersion}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { MoreHorizontal, Edit, Copy, Archive, Eye, CheckCircle, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import type { TemplateKind } from '@/types/consent'

const KIND_LABELS: Record<TemplateKind, string> = {
  tattoo: 'Tattoo',
  piercing: 'Piercing',
  pmu: 'PMU',
  touch_up: 'Touch-up',
  minor: 'Minor',
  custom: 'Custom',
}

export interface TemplateCardData {
  id: string
  name: string
  kind: TemplateKind
  version: number
  submission_count: number
  is_default: boolean
  requires_guardian: boolean
  required_for_booking: boolean
  is_active: boolean
  created_at: string
}

interface TemplateCardProps {
  template: TemplateCardData
  onRefresh?: () => void
}

export function TemplateCard({ template, onRefresh }: TemplateCardProps) {
  const router = useRouter()
  const [archiveDialog, setArchiveDialog] = useState(false)
  const [isPending, startTransition] = useTransition()

  const handleDuplicate = () => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/consent-forms/templates/${template.id}/duplicate`, {
          method: 'POST',
        })
        if (!res.ok) throw new Error()
        const body = (await res.json()) as { id: string }
        toast.success('Template duplicated')
        onRefresh?.()
        router.push(`/consent-forms/templates/${body.id}/edit`)
      } catch {
        toast.error('Failed to duplicate template')
      }
    })
  }

  const handleArchive = () => {
    startTransition(async () => {
      try {
        const res = await fetch(`/api/consent-forms/templates/${template.id}`, {
          method: 'DELETE',
        })
        if (!res.ok) throw new Error()
        toast.success('Template archived')
        setArchiveDialog(false)
        onRefresh?.()
      } catch {
        toast.error('Failed to archive template')
      }
    })
  }

  return (
    <>
      <div
        className={cn(
          'group relative rounded-xl border border-border bg-card p-4 transition-colors',
          'hover:border-border/80 hover:bg-card/80',
          !template.is_active && 'opacity-60'
        )}
      >
        {/* Kind badge */}
        <div className="mb-3 flex items-center gap-2">
          <span className={cn('badge-kind-tattoo text-xs px-2 py-0.5 rounded-full font-medium', `badge-kind-${template.kind}`)}>
            {KIND_LABELS[template.kind]}
          </span>
          {template.is_default && (
            <span className="flex items-center gap-1 text-xs text-green-500">
              <CheckCircle className="h-3 w-3" />
              Default
            </span>
          )}
          {!template.is_active && (
            <span className="text-xs text-muted-foreground">Archived</span>
          )}
        </div>

        {/* Name + version */}
        <h3 className="mb-1 text-sm font-medium leading-tight text-foreground line-clamp-2">
          {template.name}
        </h3>
        <p className="text-xs text-muted-foreground">v{template.version}</p>

        {/* Metadata row */}
        <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-1">
          <span className="text-xs text-muted-foreground">
            {template.submission_count} submission{template.submission_count !== 1 ? 's' : ''}
          </span>
          {template.requires_guardian && (
            <span className="text-xs text-amber-500">Guardian req.</span>
          )}
          {template.required_for_booking && (
            <span className="text-xs text-blue-500">Booking req.</span>
          )}
        </div>

        {/* Actions */}
        <div className="mt-4 flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            className="h-7 gap-1 text-xs flex-1"
            onClick={() => router.push(`/consent-forms/templates/${template.id}/edit`)}
          >
            <Edit className="h-3 w-3" />
            Edit
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="sm" variant="ghost" className="h-7 w-7 p-0">
                <MoreHorizontal className="h-3.5 w-3.5" />
                <span className="sr-only">More actions</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="text-xs">
              <DropdownMenuItem
                onClick={() => router.push(`/api/consent-forms/templates/${template.id}/preview`)}
                className="gap-2 text-xs"
              >
                <Eye className="h-3.5 w-3.5" />
                Preview
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={handleDuplicate}
                disabled={isPending}
                className="gap-2 text-xs"
              >
                {isPending ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : (
                  <Copy className="h-3.5 w-3.5" />
                )}
                Duplicate
              </DropdownMenuItem>
              {template.is_active && (
                <>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem
                    onClick={() => setArchiveDialog(true)}
                    className="gap-2 text-xs text-destructive focus:text-destructive"
                  >
                    <Archive className="h-3.5 w-3.5" />
                    Archive
                  </DropdownMenuItem>
                </>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      <Dialog open={archiveDialog} onOpenChange={setArchiveDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Archive template?</DialogTitle>
            <DialogDescription>
              &ldquo;{template.name}&rdquo; will be hidden from future use. Existing submissions
              are unaffected. You can restore it later.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setArchiveDialog(false)}>
              Cancel
            </Button>
            <Button variant="destructive" onClick={handleArchive} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Archive
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { Plus, Loader2 } from 'lucide-react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { TemplateCard, type TemplateCardData } from './TemplateCard'
import type { TemplateKind } from '@/types/consent'

type KindFilter = TemplateKind | 'all'

export function TemplatesGrid() {
  const router = useRouter()
  const [templates, setTemplates] = useState<TemplateCardData[]>([])
  const [kindFilter, setKindFilter] = useState<KindFilter>('all')
  const [showArchived, setShowArchived] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchTemplates = useCallback(async () => {
    setIsLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams()
      if (kindFilter !== 'all') params.set('kind', kindFilter)
      if (!showArchived) params.set('active', 'true')
      const res = await fetch(`/api/consent-forms/templates?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to load templates')
      const body = (await res.json()) as { data: TemplateCardData[] }
      setTemplates(body.data ?? [])
    } catch {
      setError('Failed to load templates. Please refresh.')
    } finally {
      setIsLoading(false)
    }
  }, [kindFilter, showArchived])

  useEffect(() => {
    void fetchTemplates()
  }, [fetchTemplates])

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex items-center gap-3">
        <Select
          value={kindFilter}
          onValueChange={(v) => setKindFilter(v as KindFilter)}
        >
          <SelectTrigger className="h-8 w-36 text-xs">
            <SelectValue placeholder="All types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="text-xs">All types</SelectItem>
            <SelectItem value="tattoo" className="text-xs">Tattoo</SelectItem>
            <SelectItem value="piercing" className="text-xs">Piercing</SelectItem>
            <SelectItem value="pmu" className="text-xs">PMU</SelectItem>
            <SelectItem value="touch_up" className="text-xs">Touch-up</SelectItem>
            <SelectItem value="minor" className="text-xs">Minor</SelectItem>
            <SelectItem value="custom" className="text-xs">Custom</SelectItem>
          </SelectContent>
        </Select>

        <Button
          variant={showArchived ? 'secondary' : 'ghost'}
          size="sm"
          className="h-8 text-xs"
          onClick={() => setShowArchived((v) => !v)}
        >
          {showArchived ? 'Hide archived' : 'Show archived'}
        </Button>

        <div className="ml-auto">
          <Button
            size="sm"
            className="h-8 gap-1.5 text-xs"
            onClick={() => router.push('/consent-forms/templates/new')}
          >
            <Plus className="h-3.5 w-3.5" />
            New Template
          </Button>
        </div>
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="flex items-center justify-center py-16 text-muted-foreground">
          <Loader2 className="h-5 w-5 animate-spin" />
        </div>
      )}

      {/* Error */}
      {!isLoading && error && (
        <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">
          {error}
        </div>
      )}

      {/* Empty */}
      {!isLoading && !error && templates.length === 0 && (
        <div className="rounded-xl border border-dashed border-border bg-muted/20 px-6 py-16 text-center">
          <p className="text-sm font-medium text-foreground">No templates yet</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Create your first consent form template to start collecting signatures.
          </p>
          <Button
            size="sm"
            className="mt-4 gap-1.5 text-xs"
            onClick={() => router.push('/consent-forms/templates/new')}
          >
            <Plus className="h-3.5 w-3.5" />
            New Template
          </Button>
        </div>
      )}

      {/* Grid */}
      {!isLoading && !error && templates.length > 0 && (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {templates.map((t) => (
            <TemplateCard key={t.id} template={t} onRefresh={fetchTemplates} />
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { Plus, Trash2, Loader2, Save, FlaskConical, CheckCircle, XCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import type { ReachBatchAnswer } from '@/types/consent'

interface ReachInkRecord extends ReachBatchAnswer {
  id?: string
}

interface ReachInkEditorProps {
  submissionId: string
  initialRecords: ReachInkRecord[]
  readOnly?: boolean
}

const EMPTY_RECORD: ReachBatchAnswer = {
  ink_brand: '',
  ink_color: '',
  ink_product_code: '',
  batch_number: '',
  manufacture_date: '',
  expiry_date: '',
  reach_compliant: true,
  sds_url: '',
}

export function ReachInkEditor({
  submissionId,
  initialRecords,
  readOnly = false,
}: ReachInkEditorProps) {
  const [records, setRecords] = useState<ReachInkRecord[]>(initialRecords)
  const [isPending, startTransition] = useTransition()

  const update = (index: number, field: keyof ReachBatchAnswer, value: ReachBatchAnswer[keyof ReachBatchAnswer]) => {
    setRecords((prev) => {
      const next = [...prev]
      next[index] = { ...next[index], [field]: value }
      return next
    })
  }

  const addRecord = () => {
    setRecords((prev) => [...prev, { ...EMPTY_RECORD }])
  }

  const removeRecord = (index: number) => {
    setRecords((prev) => prev.filter((_, i) => i !== index))
  }

  const handleSave = () => {
    // Validate — each record needs brand, color, batch
    for (const [i, r] of records.entries()) {
      if (!r.ink_brand.trim() || !r.ink_color.trim() || !r.batch_number.trim()) {
        toast.error(`Record ${i + 1}: brand, color, and batch number are required`)
        return
      }
    }

    startTransition(async () => {
      try {
        const res = await fetch(
          `/api/consent-forms/submissions/${submissionId}/reach-records`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ records }),
          }
        )
        if (!res.ok) throw new Error()
        const body = (await res.json()) as { data: ReachInkRecord[] }
        setRecords(body.data)
        toast.success('REACH records saved')
      } catch {
        toast.error('Failed to save REACH records')
      }
    })
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2">
        <FlaskConical className="h-4 w-4 text-muted-foreground shrink-0" />
        <p className="text-sm font-medium">REACH Ink Records</p>
        {records.length > 0 && (
          <span className="text-xs text-muted-foreground">({records.length} ink{records.length !== 1 ? 's' : ''})</span>
        )}
      </div>

      {records.length === 0 && (
        <p className="text-xs text-muted-foreground">
          No ink records added. Add inks used in this session for REACH compliance.
        </p>
      )}

      <div className="space-y-4">
        {records.map((record, index) => (
          <div
            key={index}
            className="rounded-lg border border-border bg-muted/20 p-3 space-y-3"
          >
            <div className="flex items-center justify-between">
              <p className="text-xs font-medium text-muted-foreground">Ink #{index + 1}</p>
              {!readOnly && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="h-6 w-6 text-muted-foreground hover:text-destructive"
                  onClick={() => removeRecord(index)}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              )}
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">Brand *</Label>
                <Input
                  value={record.ink_brand}
                  onChange={(e) => update(index, 'ink_brand', e.target.value)}
                  className="h-7 text-xs"
                  readOnly={readOnly}
                  placeholder="e.g. World Famous"
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Color *</Label>
                <Input
                  value={record.ink_color}
                  onChange={(e) => update(index, 'ink_color', e.target.value)}
                  className="h-7 text-xs"
                  readOnly={readOnly}
                  placeholder="e.g. Midnight Black"
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Product code</Label>
                <Input
                  value={record.ink_product_code ?? ''}
                  onChange={(e) => update(index, 'ink_product_code', e.target.value || null)}
                  className="h-7 text-xs"
                  readOnly={readOnly}
                  placeholder="SKU / ref"
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Batch number *</Label>
                <Input
                  value={record.batch_number}
                  onChange={(e) => update(index, 'batch_number', e.target.value)}
                  className="h-7 text-xs"
                  readOnly={readOnly}
                  placeholder="From bottle label"
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Manufacture date</Label>
                <Input
                  type="date"
                  value={record.manufacture_date ?? ''}
                  onChange={(e) => update(index, 'manufacture_date', e.target.value || null)}
                  className="h-7 text-xs"
                  readOnly={readOnly}
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Expiry date</Label>
                <Input
                  type="date"
                  value={record.expiry_date ?? ''}
                  onChange={(e) => update(index, 'expiry_date', e.target.value || null)}
                  className="h-7 text-xs"
                  readOnly={readOnly}
                />
              </div>
            </div>

            <div className="space-y-1">
              <Label className="text-xs">SDS URL</Label>
              <Input
                value={record.sds_url ?? ''}
                onChange={(e) => update(index, 'sds_url', e.target.value || null)}
                className="h-7 text-xs"
                readOnly={readOnly}
                placeholder="https://…"
              />
            </div>

            <div className="flex items-center justify-between">
              <Label className="text-xs">REACH compliant</Label>
              <div className="flex items-center gap-1.5">
                {record.reach_compliant ? (
                  <CheckCircle className="h-3.5 w-3.5 text-green-500" />
                ) : (
                  <XCircle className="h-3.5 w-3.5 text-destructive" />
                )}
                {!readOnly && (
                  <Switch
                    checked={record.reach_compliant}
                    onCheckedChange={(v) => update(index, 'reach_compliant', v)}
                    aria-label="REACH compliant"
                  />
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {!readOnly && (
        <div className="flex items-center gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-7 gap-1 text-xs"
            onClick={addRecord}
          >
            <Plus className="h-3.5 w-3.5" />
            Add ink
          </Button>
          {records.length > 0 && (
            <Button
              type="button"
              size="sm"
              className="h-7 gap-1 text-xs"
              onClick={handleSave}
              disabled={isPending}
            >
              {isPending ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <Save className="h-3.5 w-3.5" />
              )}
              Save records
            </Button>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Download, Loader2, AlertCircle, FileText } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { ConsentStatusBadge } from '@/components/consent/ConsentStatusBadge'
import { AuditCard } from './AuditCard'
import { ReachInkEditor } from './ReachInkEditor'
import { SectionRenderer } from '@/components/consent/templates/SectionRenderer'
import type { ConsentSection, ReachBatchAnswer } from '@/types/consent'
import type { SubmissionStatus } from '@/types/consent'
import { ScrollArea } from '@/components/ui/scroll-area'

interface ReachRecord extends ReachBatchAnswer {
  id?: string
}

interface SubmissionDetail {
  id: string
  consent_token: string
  status: SubmissionStatus
  signed_at: string
  signer_name: string
  signer_email: string | null
  signer_phone: string | null
  signer_dob: string | null
  ip_country: string | null
  user_agent: string | null
  audit_hash: string
  expires_at: string | null
  pdf_path: string | null
  answers: Record<string, unknown>
  template_snapshot: {
    id: string
    name: string
    kind: string
    version: number
    sections: ConsentSection[]
    requires_guardian: boolean
    retention_years: number
  }
  signature_url: string | null
  guardian_url: string | null
  pdf_url: string | null
  reach_records: ReachRecord[]
  guardian_name: string | null
  guardian_relationship: string | null
}

interface SubmissionViewProps {
  submissionId: string
}

export function SubmissionView({ submissionId }: SubmissionViewProps) {
  const [data, setData] = useState<SubmissionDetail | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    const load = async () => {
      setIsLoading(true)
      setError(null)
      try {
        const res = await fetch(`/api/consent-forms/submissions/${submissionId}`)
        if (!res.ok) throw new Error('Failed to load submission')
        const body = (await res.json()) as { data: SubmissionDetail }
        if (!cancelled) setData(body.data)
      } catch {
        if (!cancelled) setError('Failed to load submission. Please refresh.')
      } finally {
        if (!cancelled) setIsLoading(false)
      }
    }
    void load()
    return () => { cancelled = true }
  }, [submissionId])

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
        <AlertCircle className="h-8 w-8 text-destructive" />
        <p className="text-sm text-muted-foreground">{error ?? 'Submission not found'}</p>
      </div>
    )
  }

  const { template_snapshot: snapshot } = data
  const sortedSections = [...snapshot.sections].sort((a, b) => a.order - b.order)

  return (
    <div className="flex h-full gap-6">
      {/* Main content */}
      <ScrollArea className="flex-1 min-w-0">
        <div className="space-y-6 p-6">
          {/* Header */}
          <div className="flex items-start justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-lg font-semibold">{snapshot.name}</h2>
              <p className="text-xs text-muted-foreground">
                v{snapshot.version} · Signed by {data.signer_name}
                {data.signer_email && ` · ${data.signer_email}`}
              </p>
            </div>
            <div className="flex shrink-0 items-center gap-2">
              <ConsentStatusBadge status={data.status} />
              {data.pdf_url && (
                <Button
                  size="sm"
                  variant="outline"
                  className="h-8 gap-1.5 text-xs"
                  asChild
                >
                  <a href={data.pdf_url} target="_blank" rel="noreferrer" download>
                    <Download className="h-3.5 w-3.5" />
                    PDF
                  </a>
                </Button>
              )}
              {!data.pdf_url && (
                <div className="flex items-center gap-1 text-xs text-muted-foreground">
                  <FileText className="h-3.5 w-3.5" />
                  PDF generating…
                </div>
              )}
            </div>
          </div>

          {/* Sections rendered from snapshot */}
          <div className="space-y-6">
            {sortedSections.map((section) => (
              <div key={section.id} className="space-y-2">
                <SectionRenderer
                  section={section}
                  isPreview
                  answer={data.answers[section.id]}
                />
              </div>
            ))}
          </div>

          {/* Signature */}
          {data.signature_url && (
            <div className="rounded-xl border border-border bg-card p-4 space-y-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                Signature
