                src={data.signature_url}
                alt="Client signature"
                className="max-h-24 w-auto rounded bg-white"
              />
              <p className="text-xs text-muted-foreground">{data.signer_name}</p>
            </div>
          )}

          {/* Guardian signature */}
          {data.guardian_url && (
            <div className="rounded-xl border border-amber-500/30 bg-amber-500/5 p-4 space-y-2">
              <p className="text-xs font-medium text-amber-500 uppercase tracking-wider">
                Guardian Signature
              </p>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={data.guardian_url}
                alt="Guardian signature"
                className="max-h-24 w-auto rounded bg-white"
              />
              <p className="text-xs text-muted-foreground">
                {data.guardian_name}
                {data.guardian_relationship && ` (${data.guardian_relationship})`}
              </p>
            </div>
          )}

          {/* REACH records */}
          <div className="rounded-xl border border-border bg-card p-4">
            <ReachInkEditor
              submissionId={submissionId}
              initialRecords={data.reach_records}
            />
          </div>
        </div>
      </ScrollArea>

      {/* Right panel — audit */}
      <div className="w-72 shrink-0 space-y-4 p-4">
        <AuditCard
          signedAt={data.signed_at}
          ipCountry={data.ip_country}
          userAgent={data.user_agent}
          auditHash={data.audit_hash}
          templateVersion={snapshot.version}
          expiresAt={data.expires_at}
          retentionYears={snapshot.retention_years}
        />
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import {
  Loader2,
  Download,
  AlertCircle,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { ConsentStatusBadge } from '@/components/consent/ConsentStatusBadge'
import { toast } from 'sonner'
import type { SubmissionStatus } from '@/types/consent'

interface SubmissionRow {
  id: string
  status: SubmissionStatus
  signed_at: string
  signer_name: string
  signer_email: string | null
  template_name: string
  template_version: number
  template_kind: string
  has_guardian: boolean
  has_pdf: boolean
}

interface SubmissionsResponse {
  data: SubmissionRow[]
  next_cursor: string | null
  count: number
}

const PAGE_SIZE = 20

export function SubmissionsTable() {
  const router = useRouter()
  const [rows, setRows] = useState<SubmissionRow[]>([])
  const [cursor, setCursor] = useState<string | null>(null)
  const [cursors, setCursors] = useState<string[]>([]) // navigation stack
  const [statusFilter, setStatusFilter] = useState<SubmissionStatus | 'all'>('all')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [isBulkExporting, setIsBulkExporting] = useState(false)
  const [nextCursor, setNextCursor] = useState<string | null>(null)

  const fetchRows = useCallback(
    async (pageCursor: string | null) => {
      setIsLoading(true)
      setError(null)
      try {
        const params = new URLSearchParams()
        params.set('limit', String(PAGE_SIZE))
        if (pageCursor) params.set('cursor', pageCursor)
        if (statusFilter !== 'all') params.set('status', statusFilter)

        const res = await fetch(`/api/consent-forms/submissions?${params.toString()}`)
        if (!res.ok) throw new Error()
        const body = (await res.json()) as SubmissionsResponse
        setRows(body.data)
        setNextCursor(body.next_cursor)
        setSelected(new Set())
      } catch {
        setError('Failed to load submissions')
      } finally {
        setIsLoading(false)
      }
    },
    [statusFilter]
  )

  useEffect(() => {
    // Reset pagination when filter changes
    setCursor(null)
    setCursors([])
    void fetchRows(null)
  }, [fetchRows])

  const handleNext = () => {
    if (!nextCursor) return
    setCursors((prev) => [...prev, cursor ?? ''])
    setCursor(nextCursor)
    void fetchRows(nextCursor)
  }

  const handlePrev = () => {
    const prevCursors = [...cursors]
    const prev = prevCursors.pop() ?? null
    setCursors(prevCursors)
    setCursor(prev)
    void fetchRows(prev)
  }

  const toggleSelect = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const toggleAll = () => {
    if (selected.size === rows.length) {
      setSelected(new Set())
    } else {
      setSelected(new Set(rows.map((r) => r.id)))
    }
  }

  const handleBulkExport = async () => {
    if (selected.size === 0) return
    setIsBulkExporting(true)
    try {
      const ids = [...selected].join(',')
      const res = await fetch(`/api/consent-forms/submissions/bulk-export?ids=${ids}`)
      if (!res.ok) throw new Error()
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `consent-export-${Date.now()}.zip`
      a.click()
      URL.revokeObjectURL(url)
      toast.success(`Exported ${selected.size} submission${selected.size !== 1 ? 's' : ''}`)
      setSelected(new Set())
    } catch {
      toast.error('Bulk export failed')
    } finally {
      setIsBulkExporting(false)
    }
  }

  return (
    <div className="space-y-3">
      {/* Toolbar */}
      <div className="flex items-center gap-3">
        <Select
          value={statusFilter}
          onValueChange={(v) => setStatusFilter(v as SubmissionStatus | 'all')}
        >
          <SelectTrigger className="h-8 w-36 text-xs">
            <SelectValue placeholder="All statuses" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="text-xs">All statuses</SelectItem>
            <SelectItem value="signed" className="text-xs">Signed</SelectItem>
            <SelectItem value="opened" className="text-xs">Opened</SelectItem>
            <SelectItem value="pending" className="text-xs">Pending</SelectItem>
            <SelectItem value="expired" className="text-xs">Expired</SelectItem>
            <SelectItem value="soft_deleted" className="text-xs">Deleted</SelectItem>
          </SelectContent>
        </Select>

        {selected.size > 0 && (
          <Button
            size="sm"
            variant="outline"
            className="h-8 gap-1.5 text-xs"
            onClick={handleBulkExport}
            disabled={isBulkExporting}
          >
            {isBulkExporting ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Download className="h-3.5 w-3.5" />
            )}
            Export {selected.size} PDF{selected.size !== 1 ? 's' : ''}
          </Button>
        )}
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
        </div>
      )}

      {/* Error */}
      {!isLoading && error && (
        <div className="flex items-center gap-2 rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">
          <AlertCircle className="h-4 w-4 shrink-0" />
          {error}
        </div>
      )}

      {/* Empty */}
      {!isLoading && !error && rows.length === 0 && (
        <div className="rounded-xl border border-dashed border-border bg-muted/20 px-6 py-16 text-center">
          <p className="text-sm font-medium text-foreground">No submissions</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Consent submissions will appear here once clients sign their forms.
          </p>
        </div>
      )}

      {/* Table */}
      {!isLoading && !error && rows.length > 0 && (
        <div className="rounded-xl border border-border overflow-hidden">
          <table className="w-full text-xs">
            <thead className="border-b border-border bg-muted/30">
              <tr>
                <th className="w-8 px-3 py-2.5">
                  <input
                    type="checkbox"
                    checked={selected.size === rows.length && rows.length > 0}
                    onChange={toggleAll}
                    className="rounded border-border"
                    aria-label="Select all"
                  />
                </th>
                <th className="px-3 py-2.5 text-left font-medium text-muted-foreground">Signer</th>
                <th className="px-3 py-2.5 text-left font-medium text-muted-foreground">Template</th>
                <th className="px-3 py-2.5 text-left font-medium text-muted-foreground">Signed</th>
                <th className="px-3 py-2.5 text-left font-medium text-muted-foreground">Status</th>
                <th className="w-8 px-3 py-2.5" />
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {rows.map((row) => (
                <tr
                  key={row.id}
                  className="cursor-pointer bg-card hover:bg-muted/30 transition-colors"
                  onClick={() => router.push(`/consent-forms/submissions/${row.id}`)}
                >
                  <td className="px-3 py-2.5" onClick={(e) => e.stopPropagation()}>
                    <input
                      type="checkbox"
                      checked={selected.has(row.id)}
                      onChange={() => toggleSelect(row.id)}
                      className="rounded border-border"
                      aria-label={`Select ${row.signer_name}`}
                    />
                  </td>
                  <td className="px-3 py-2.5">
                    <p className="font-medium text-foreground">{row.signer_name}</p>
                    {row.signer_email && (
                      <p className="text-muted-foreground">{row.signer_email}</p>
                    )}
                  </td>
                  <td className="px-3 py-2.5">
                    <p className="text-foreground">{row.template_name}</p>
                    <p className="text-muted-foreground">v{row.template_version}</p>
                  </td>
                  <td className="px-3 py-2.5 text-muted-foreground">
                    {new Date(row.signed_at).toLocaleDateString(undefined, {
                      dateStyle: 'medium',
                    })}
                  </td>
                  <td className="px-3 py-2.5">
                    <ConsentStatusBadge status={row.status} />
                  </td>
                  <td className="px-3 py-2.5 text-right">
                    {row.has_pdf && (
                      <span className="text-muted-foreground">PDF</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Pagination */}
          <div className="flex items-center justify-between border-t border-border bg-muted/20 px-4 py-2">
            <p className="text-xs text-muted-foreground">
              Showing {rows.length} result{rows.length !== 1 ? 's' : ''}
            </p>
            <div className="flex items-center gap-1">
              <Button
                size="icon"
                variant="ghost"
                className="h-7 w-7"
                onClick={handlePrev}
                disabled={cursors.length === 0}
                aria-label="Previous page"
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
              <Button
                size="icon"
                variant="ghost"
                className="h-7 w-7"
                onClick={handleNext}
                disabled={!nextCursor}
                aria-label="Next page"
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

