'use client'

import { useState, useEffect } from 'react'
import { CheckCircle, Download, Loader2, ExternalLink } from 'lucide-react'
import { Button } from '@/components/ui/button'

interface SuccessStateProps {
  submissionId: string
  consentToken: string
  viewUrl: string
  studioName: string
}

export function SuccessState({
  submissionId,
  consentToken,
  viewUrl,
  studioName,
}: SuccessStateProps) {
  const [pdfReady, setPdfReady] = useState(false)
  const [pdfUrl, setPdfUrl] = useState<string | null>(null)
  const [polling, setPolling] = useState(true)

  // Poll for PDF readiness (max 60s)
  useEffect(() => {
    if (!polling) return
    let attempts = 0
    const maxAttempts = 12 // 12 × 5s = 60s

    const check = async () => {
      attempts++
      try {
        const res = await fetch(`/api/public/consent/view/${consentToken}`)
        if (res.ok) {
          const body = (await res.json()) as { pdf_path?: string | null; pdf_url?: string | null }
          if (body.pdf_path && body.pdf_url) {
            setPdfUrl(body.pdf_url)
            setPdfReady(true)
            setPolling(false)
            return
          }
        }
      } catch {
        // silent — keep polling
      }
      if (attempts >= maxAttempts) {
        setPolling(false)
      }
    }

    const id = setInterval(() => void check(), 5000)
    void check() // run immediately
    return () => clearInterval(id)
  }, [consentToken, polling])

  return (
    <div className="signing-page flex min-h-dvh items-center justify-center p-4">
      <div className="signing-card mx-auto w-full max-w-md text-center space-y-6">
        {/* Icon */}
        <div className="flex justify-center">
          <div className="flex h-16 w-16 items-center justify-center rounded-full bg-green-500/10">
            <CheckCircle className="h-8 w-8 text-green-500" />
          </div>
        </div>

        {/* Headline */}
        <div className="space-y-2">
          <h1 className="text-xl font-semibold text-foreground">Form submitted</h1>
          <p className="text-sm text-muted-foreground">
            Your consent form for{' '}
            <span className="font-medium text-foreground">{studioName}</span> has been
            signed and recorded.
          </p>
        </div>

        {/* PDF CTA */}
        <div className="rounded-xl border border-border bg-card p-4 space-y-3">
          <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
            Your copy
          </p>
          {pdfReady && pdfUrl ? (
            <Button className="w-full gap-2" asChild>
              <a href={pdfUrl} target="_blank" rel="noreferrer" download>
                <Download className="h-4 w-4" />
                Download PDF
              </a>
            </Button>
          ) : (
            <div className="flex items-center justify-center gap-2 text-sm text-muted-foreground py-2">
              <Loader2 className="h-4 w-4 animate-spin" />
              {polling ? 'Generating PDF…' : 'PDF unavailable — check your email.'}
            </div>
          )}
          <Button variant="outline" className="w-full gap-2" asChild>
            <a href={viewUrl} target="_blank" rel="noreferrer">
              <ExternalLink className="h-4 w-4" />
              View signed form
            </a>
          </Button>
        </div>

        <p className="text-xs text-muted-foreground">
          A confirmation will be sent to your email if provided.
        </p>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect, useTransition } from 'react'
import { AlertTriangle, ChevronDown, ChevronUp } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { SignaturePad } from '@/components/consent/SignaturePad'
import { SectionRenderer } from '@/components/consent/templates/SectionRenderer'
import { ProgressIndicator } from './ProgressIndicator'
import { SubmitButton } from './SubmitButton'
import { SuccessState } from './SuccessState'
import type {
  PublicConsentRequest,
  SectionAnswers,
  ConsentSection,
  ConsentDraftProgress,
  PublicSubmitResponse,
} from '@/types/consent'
import { cn } from '@/lib/utils'

interface PublicSignFlowProps {
  request: PublicConsentRequest
}

const DRAFT_KEY = (token: string) => `inkos:consent:${token}:progress`

function loadDraft(token: string): ConsentDraftProgress | null {
  try {
    const raw = localStorage.getItem(DRAFT_KEY(token))
    if (!raw) return null
    return JSON.parse(raw) as ConsentDraftProgress
  } catch {
    return null
  }
}

function saveDraft(token: string, progress: ConsentDraftProgress) {
  try {
    localStorage.setItem(DRAFT_KEY(token), JSON.stringify(progress))
  } catch {
    // quota exceeded — silent
  }
}

function clearDraft(token: string) {
  try {
    localStorage.removeItem(DRAFT_KEY(token))
  } catch {
    // silent
  }
}

function isSectionRequired(section: ConsentSection): boolean {
  return section.required
}

function isAnswerComplete(section: ConsentSection, answers: SectionAnswers): boolean {
  const value = answers[section.id]
  if (!isSectionRequired(section)) return true
  if (section.kind === 'heading' || section.kind === 'paragraph' || section.kind === 'reach_batch_record') return true
  if (section.kind === 'checkbox') return value === true
  if (section.kind === 'signature' || section.kind === 'initials') return typeof value === 'string' && value.length > 0
  if (section.kind === 'text_input') return typeof value === 'string' && value.trim().length > 0
  if (section.kind === 'date') return typeof value === 'string' && value.length > 0
  if (section.kind === 'dropdown') return typeof value === 'string' && value.length > 0
  if (section.kind === 'file_upload') return typeof value === 'string' && value.length > 0
  if (section.kind === 'ink_disclosure') return value === true
  return true
}

export function PublicSignFlow({ request }: PublicSignFlowProps) {
  const { template, studio, client, request_token: token } = request
  const sortedSections = [...template.sections].sort((a, b) => a.order - b.order)

  // Draft restore
  const draft = typeof window !== 'undefined' ? loadDraft(token) : null

  const [answers, setAnswers] = useState<SectionAnswers>(draft?.answers ?? {})
  const [mainSigPng, setMainSigPng] = useState<string>('')
  const [guardianSigPng, setGuardianSigPng] = useState<string>('')
  const [signerName, setSignerName] = useState(
    client ? `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}` : ''
  )
  const [signerEmail, setSignerEmail] = useState(client?.email ?? '')
  const [signerDob, setSignerDob] = useState('')
  const [guardianName, setGuardianName] = useState('')
  const [guardianRelationship, setGuardianRelationship] = useState('')
  const [expandedSections, setExpandedSections] = useState<Set<string>>(
    new Set([sortedSections[0]?.id].filter(Boolean) as string[])
  )
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [isPending, startTransition] = useTransition()
  const [successData, setSuccessData] = useState<{
    submissionId: string
    consentToken: string
    viewUrl: string
  } | null>(null)

  // Persist draft on answers change
  useEffect(() => {
    const completed = sortedSections
      .filter((s) => isAnswerComplete(s, answers))
      .map((s) => s.id)
    saveDraft(token, { answers, completedSections: completed, savedAt: new Date().toISOString() })
  }, [answers, token, sortedSections])

  const setAnswer = useCallback((sectionId: string, value: SectionAnswers[string]) => {
    setAnswers((prev) => ({ ...prev, [sectionId]: value }))
  }, [])

  const toggleExpanded = (id: string) => {
    setExpandedSections((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  // Required sections (excluding heading/paragraph/reach_batch_record)
  const requiredSections = sortedSections.filter((s) => isSectionRequired(s))
  const completedRequired = requiredSections.filter((s) => isAnswerComplete(s, answers))
  const allRequiredFilled =
    completedRequired.length === requiredSections.length &&
    mainSigPng.length > 0 &&
    signerName.trim().length > 0 &&
    (!template.requires_guardian || guardianSigPng.length > 0)

  const handleSubmit = useCallback(() => {
    setSubmitError(null)
    startTransition(async () => {
      try {
        const payload = {
          request_token: token,
          answers,
          signature_png_base64: mainSigPng.split(',')[1] ?? mainSigPng,
          signer_name: signerName.trim(),
          signer_email: signerEmail.trim() || null,
          signer_dob: signerDob || null,
          guardian: template.requires_guardian
            ? {
                name: guardianName.trim(),
                relationship: guardianRelationship.trim() || 'guardian',
                signature_png_base64: guardianSigPng.split(',')[1] ?? guardianSigPng,
              }
            : null,
        }

        const res = await fetch('/api/public/consent/submit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })

        const body = (await res.json()) as PublicSubmitResponse

        if ('error' in body && body.error) {
          const errorMessages: Record<string, string> = {
            already_signed: 'This form has already been signed.',
            expired: 'This consent request has expired. Please contact the studio.',
            request_cancelled: 'This consent request has been cancelled.',
            request_not_found: 'Consent request not found.',
            submission_failed: 'Submission failed. Please try again.',
          }
          setSubmitError(errorMessages[body.error] ?? 'Submission failed. Please try again.')
          return
        }

        if ('consent_token' in body) {
          clearDraft(token)
          setSuccessData({
            submissionId: body.submission_id,
            consentToken: body.consent_token,
            viewUrl: body.view_url,
          })
        }
      } catch {
        setSubmitError('Network error. Please check your connection and try again.')
      }
    })
  }, [
    token,
    answers,
    mainSigPng,
    guardianSigPng,
    signerName,
    signerEmail,
    signerDob,
    guardianName,
    guardianRelationship,
    template.requires_guardian,
  ])

  if (successData) {
    return (
      <SuccessState
        submissionId={successData.submissionId}
        consentToken={successData.consentToken}
        viewUrl={successData.viewUrl}
        studioName={studio.name}
      />
    )
  }

  return (
    <div className="signing-page min-h-dvh">
      <div className="mx-auto max-w-xl px-4 py-8 space-y-6">
        {/* Studio header */}
        <div className="text-center space-y-2">
          {studio.logo_url && (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studio.logo_url}
              alt={studio.name}
              className="mx-auto h-10 w-auto object-contain"
            />
          )}
          <h1 className="text-lg font-semibold text-foreground">{template.name}</h1>
          <p className="text-xs text-muted-foreground">{studio.name}</p>
        </div>

        {/* Guardian notice */}
        {template.requires_guardian && (
          <div className="flex items-start gap-2 rounded-lg border border-amber-500/30 bg-amber-500/10 p-3">
            <AlertTriangle className="h-4 w-4 shrink-0 text-amber-500 mt-0.5" />
            <p className="text-xs text-amber-600 dark:text-amber-400">
              A guardian or parent signature is required for this form.
            </p>
          </div>
        )}

        {/* Progress */}
        <ProgressIndicator
          completed={completedRequired.length}
          total={requiredSections.length}
        />

        {/* Signer info */}
        <div className="signing-card space-y-3 rounded-xl border border-border bg-card p-4">
          <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
            Your information
          </p>
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div className="space-y-1">
              <Label className="text-xs" htmlFor="signer-name">Full name *</Label>
              <Input
                id="signer-name"
                value={signerName}
                onChange={(e) => setSignerName(e.target.value)}
                placeholder="Your full legal name"
                className="h-9 text-sm"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs" htmlFor="signer-email">Email</Label>
              <Input
                id="signer-email"
                type="email"
                value={signerEmail}
                onChange={(e) => setSignerEmail(e.target.value)}
                placeholder="For your copy"
                className="h-9 text-sm"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs" htmlFor="signer-dob">Date of birth</Label>
              <Input
                id="signer-dob"
                type="date"
                value={signerDob}
                onChange={(e) => setSignerDob(e.target.value)}
                className="h-9 text-sm"
              />
            </div>
          </div>
        </div>

        {/* Sections */}
        {sortedSections.map((section) => {
          const isComplete = isAnswerComplete(section, answers)
          const isExpanded = expandedSections.has(section.id)

          return (
            <div
              key={section.id}
              className={cn(
                'signing-card rounded-xl border border-border bg-card overflow-hidden transition-colors',
                isComplete && 'border-green-500/30'
              )}
            >
              {/* Collapsible header for non-heading/paragraph sections */}
              {section.kind !== 'heading' && section.kind !== 'paragraph' && (
                <button
                  type="button"
                  className="flex w-full items-center justify-between p-4 text-left"
                  onClick={() => toggleExpanded(section.id)}
                >
                  <div className="flex items-center gap-2">
                    {isComplete ? (
                      <span className="h-2 w-2 rounded-full bg-green-500 shrink-0" />
                    ) : isSectionRequired(section) ? (
                      <span className="h-2 w-2 rounded-full bg-amber-500 shrink-0" />
                    ) : (
                      <span className="h-2 w-2 rounded-full bg-muted shrink-0" />
                    )}
                    <p className="text-sm font-medium text-foreground">
                      {section.label}
                      {isSectionRequired(section) && (
                        <span className="ml-1 text-destructive">*</span>
                      )}
                    </p>
                  </div>
                  {isExpanded ? (
                    <ChevronUp className="h-4 w-4 text-muted-foreground shrink-0" />
                  ) : (
                    <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
                  )}
                </button>
              )}

              {/* Content */}
              {(isExpanded || section.kind === 'heading' || section.kind === 'paragraph') && (
                <div className={cn('px-4 pb-4', section.kind !== 'heading' && section.kind !== 'paragraph' && 'pt-0')}>
                  <SectionRenderer
                    section={section}
                    isPreview={false}
                    answer={answers[section.id]}
                    onAnswer={(value) => setAnswer(section.id, value)}
                  />
                </div>
              )}
            </div>
          )
        })}

        {/* Main signature */}
        <div className="signing-card rounded-xl border border-border bg-card p-4 space-y-3">
          <p className="text-sm font-medium">
            Client Signature <span className="text-destructive">*</span>
          </p>
          <SignaturePad
            label="Sign here to confirm all information is accurate"
            onDone={(png) => setMainSigPng(png)}
            onClear={() => setMainSigPng('')}
          />
        </div>

        {/* Guardian signature */}
        {template.requires_guardian && (
          <div className="signing-card rounded-xl border border-amber-500/30 bg-amber-500/5 p-4 space-y-3">
            <p className="text-sm font-medium text-amber-600 dark:text-amber-400">
              Guardian / Parent Signature <span className="text-destructive">*</span>
            </p>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">Guardian name *</Label>
                <Input
                  value={guardianName}
                  onChange={(e) => setGuardianName(e.target.value)}
                  className="h-8 text-sm"
                  placeholder="Full name"
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Relationship</Label>
                <Input
                  value={guardianRelationship}
                  onChange={(e) => setGuardianRelationship(e.target.value)}
                  className="h-8 text-sm"
                  placeholder="e.g. Parent"
                />
              </div>
            </div>
            <SignaturePad
              label="Guardian signature"
              onDone={(png) => setGuardianSigPng(png)}
              onClear={() => setGuardianSigPng('')}
            />
          </div>
        )}

        {/* Submit error */}
        {submitError && (
          <div
            className="flex items-start gap-2 rounded-lg border border-destructive/30 bg-destructive/10 p-3"
            role="alert"
          >
            <AlertTriangle className="h-4 w-4 shrink-0 text-destructive mt-0.5" />
            <p className="text-sm text-destructive">{submitError}</p>
          </div>
        )}

        {/* Submit */}
        <SubmitButton
          allRequiredFilled={allRequiredFilled}
          isSubmitting={isPending}
          onClick={handleSubmit}
        />

        <p className="text-center text-xs text-muted-foreground pb-8">
          This form is provided by {studio.name}. Your data is stored securely and will be
          retained for {template.retention_years} years.
        </p>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useTransition } from 'react'
import { Send, Loader2, Mail, MessageSquare } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { toast } from 'sonner'

interface TemplateMeta {
  id: string
  name: string
  kind: string
}

interface SendConsentRequestModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  bookingId: string
  clientName: string
  clientEmail: string | null
  clientPhone: string | null
  /** Pre-selected template id */
  templateId?: string
}

const DEFAULT_EMAIL_TEMPLATE = (clientName: string, studioName: string) =>
  `Hi ${clientName},\n\nPlease complete and sign your consent form before your appointment at ${studioName}.\n\nThis only takes a few minutes on your phone.\n\nThank you!`

export function SendConsentRequestModal({
  open,
  onOpenChange,
  bookingId,
  clientName,
  clientEmail,
  clientPhone,
  templateId: prefillTemplateId,
}: SendConsentRequestModalProps) {
  const [templates, setTemplates] = useState<TemplateMeta[]>([])
  const [selectedTemplateId, setSelectedTemplateId] = useState(prefillTemplateId ?? '')
  const [sendEmail, setSendEmail] = useState(!!clientEmail)
  const [sendSms, setSendSms] = useState(false)
  const [customMessage, setCustomMessage] = useState(
    DEFAULT_EMAIL_TEMPLATE(clientName, 'the studio')
  )
  const [isPending, startTransition] = useTransition()
  const [isLoadingTemplates, setIsLoadingTemplates] = useState(false)

  // Load templates on open
  useEffect(() => {
    if (!open) return
    setIsLoadingTemplates(true)
    fetch('/api/consent-forms/templates?active=true')
      .then((r) => r.json())
      .then((body: { data: TemplateMeta[] }) => {
        setTemplates(body.data ?? [])
        if (!selectedTemplateId && body.data?.[0]) {
          setSelectedTemplateId(body.data[0].id)
        }
      })
      .catch(() => { /* silent */ })
      .finally(() => setIsLoadingTemplates(false))
  }, [open, selectedTemplateId])

  const handleSend = () => {
    if (!selectedTemplateId) {
      toast.error('Please select a template')
      return
    }
    if (!sendEmail && !sendSms) {
      toast.error('Select at least one delivery channel')
      return
    }

    startTransition(async () => {
      try {
        const res = await fetch('/api/consent-requests', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            booking_id: bookingId,
            template_id: selectedTemplateId,
            send_email: sendEmail && !!clientEmail,
            send_sms: sendSms && !!clientPhone,
            custom_message: customMessage.trim() || null,
          }),
        })
        if (!res.ok) {
          const body = (await res.json()) as { error?: string }
          toast.error(body.error ?? 'Failed to send consent request')
          return
        }
        toast.success('Consent request sent')
        onOpenChange(false)
      } catch {
        toast.error('Failed to send consent request')
      }
    })
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Send Consent Form</DialogTitle>
          <DialogDescription>
            Send a consent request to{' '}
            <span className="font-medium text-foreground">{clientName}</span>
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Template select */}
          <div className="space-y-1.5">
            <Label className="text-xs">Template</Label>
            {isLoadingTemplates ? (
              <div className="flex h-9 items-center gap-2 rounded-md border border-input px-3 text-xs text-muted-foreground">
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Loading templates…
              </div>
            ) : (
              <Select
                value={selectedTemplateId}
                onValueChange={setSelectedTemplateId}
              >
                <SelectTrigger className="h-9 text-xs">
                  <SelectValue placeholder="Choose a template" />
                </SelectTrigger>
                <SelectContent>
                  {templates.map((t) => (
                    <SelectItem key={t.id} value={t.id} className="text-xs">
                      {t.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </div>

          {/* Channels */}
          <div className="space-y-2">
            <Label className="text-xs">Delivery channels</Label>
            <div className="space-y-2 rounded-lg border border-border p-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-xs">
                  <Mail className="h-3.5 w-3.5 text-muted-foreground" />
                  <span>Email</span>
                  {!clientEmail && (
                    <span className="text-muted-foreground">(no email on file)</span>
                  )}
                  {clientEmail && (
                    <span className="text-muted-foreground truncate max-w-[140px]">{clientEmail}</span>
                  )}
                </div>
                <Switch
                  checked={sendEmail && !!clientEmail}
                  onCheckedChange={setSendEmail}
                  disabled={!clientEmail}
                  aria-label="Send via email"
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-xs">
                  <MessageSquare className="h-3.5 w-3.5 text-muted-foreground" />
                  <span>SMS</span>
                  {!clientPhone && (
                    <span className="text-muted-foreground">(no phone on file)</span>
                  )}
                  {clientPhone && (
                    <span className="text-muted-foreground">{clientPhone}</span>
                  )}
                </div>
                <Switch
                  checked={sendSms && !!clientPhone}
                  onCheckedChange={setSendSms}
                  disabled={!clientPhone}
                  aria-label="Send via SMS"
                />
              </div>
            </div>
          </div>

          {/* Custom message preview */}
          <div className="space-y-1.5">
            <Label className="text-xs">Message preview</Label>
            <Textarea
              value={customMessage}
              onChange={(e) => setCustomMessage(e.target.value)}
              rows={5}
              className="text-xs resize-none"
              placeholder="Optional custom message"
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            onClick={handleSend}
            disabled={isPending || !selectedTemplateId}
            className="gap-1.5"
          >
            {isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
            Send
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

