import type { Metadata } from 'next'
import { createClient } from '@/lib/supabase/server'
import { redirect, notFound } from 'next/navigation'
import { TemplateBuilder } from '@/components/consent/templates/TemplateBuilder'
import type { ConsentSection, TemplateKind } from '@/types/consent'

export const metadata: Metadata = {
  title: 'Edit Template — InkOS',
}

interface PageProps {
  params: Promise<{ id: string }>
}

export default async function EditTemplatePage({ params }: PageProps) {
  const { id } = await params

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: template, error } = await supabase
    .from('consent_form_templates')
    .select(
      'id, name, kind, version, sections, retention_years, is_default, language, required_for_booking, requires_guardian, is_active'
    )
    .eq('id', id)
    .single()

  if (error || !template) notFound()

  // Get submission count for this template (all versions)
  const { count } = await supabase
    .from('consent_form_submissions')
    .select('id', { count: 'exact', head: true })
    .eq('template_id', id)

  return (
    <div className="flex h-[calc(100dvh-56px)] flex-col">
      <TemplateBuilder
        templateId={id}
        submissionCount={count ?? 0}
        initialValues={{
          name: template.name,
          kind: template.kind as TemplateKind,
          sections: (template.sections as ConsentSection[]) ?? [],
          retention_years: template.retention_years,
          is_default: template.is_default,
          language: template.language,
          required_for_booking: template.required_for_booking,
          requires_guardian: template.requires_guardian,
        }}
      />
    </div>
  )
}

