function renderSectionAnswer(section: ConsentSection, answers: Record<string, unknown>) {
  const answer = answers[section.id]

  switch (section.kind) {
    case 'heading': {
      const headingStyle =
        section.level === 1
          ? styles.headingH1
          : section.level === 2
            ? styles.headingH2
            : styles.headingH3
      return (
        <View style={styles.sectionContainer} key={section.id}>
          <Text style={headingStyle}>{section.label}</Text>
        </View>
      )
    }

    case 'paragraph':
      return (
        <View style={styles.sectionContainer} key={section.id}>
          <Text style={styles.sectionBody}>{section.body}</Text>
        </View>
      )

    case 'checkbox':
      return (
        <View style={styles.sectionContainer} key={section.id}>
          <View style={styles.checkboxRow}>
            <View style={styles.checkboxBox}>
              {answer === true && <Text style={styles.checkmark}>✓</Text>}
            </View>
            <Text style={styles.sectionBody}>{section.body}</Text>
          </View>
        </View>
      )

    case 'signature':
    case 'initials':
      // Signatures are rendered separately at the bottom
      return null

    case 'ink_disclosure':
      return (
        <View style={styles.sectionContainer} key={section.id}>
          <Text style={styles.sectionLabel}>{section.label}</Text>
          <Text style={styles.sectionBody}>{section.disclosure_text}</Text>
          <View style={styles.checkboxRow}>
            <View style={styles.checkboxBox}>
              {answer === true && <Text style={styles.checkmark}>✓</Text>}
            </View>
            <Text style={styles.sectionBody}>Acknowledged</Text>
