// Inactive client check — weekly Sunday 2:00 AM UTC
cron.schedule('0 2 * * 0', async () => {
  logger.info('cron: enqueueing inactive client emails')
  // Sprint 11: enqueue marketing automation jobs
})

// ── Sprint 5: GDPR consent form retention ────────────────────────────────────

// Soft-delete expired consent form submissions — weekly Monday 3:00 AM UTC
// Sets status = 'soft_deleted' on submissions where expires_at < now()
cron.schedule('0 3 * * 1', async () => {
  logger.info('cron: soft-deleting expired consent submissions')
  await purgeExpiredConsents()
})

// Hard-delete soft-deleted submissions after 90-day grace period — weekly Tuesday 3:30 AM UTC
// Deletes rows + cleans storage objects where soft_deleted_at < now() - 90 days
cron.schedule('30 3 * * 2', async () => {
  logger.info('cron: hard-deleting soft-deleted consent submissions')
  await purgeSoftDeletedConsents()
})

// ── GDPR helpers ─────────────────────────────────────────────────────────────

function getServiceRoleClient() {
  const url = process.env['NEXT_PUBLIC_SUPABASE_URL'] ?? process.env['SUPABASE_URL']
  const key = process.env['SUPABASE_SERVICE_ROLE_KEY']
  if (!url || !key) throw new Error('Missing Supabase env vars for cron worker')
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
}

/**
 * Soft-delete consent submissions whose expires_at has passed.
 * Sets status = 'soft_deleted', records soft_deleted_at = now().
 */
async function purgeExpiredConsents() {
  const log = logger.child({ job: 'purge-expired-consents' })
  const supabase = getServiceRoleClient()

  const { data, error } = await supabase.rpc('purge_expired_consent_submissions')
  if (error) {
    log.error({ err: error }, 'purge_expired_consent_submissions RPC failed')
    return
  }
  log.info({ rows: (data as number | null) ?? 0 }, 'expired consent submissions soft-deleted')
}

/**
 * Hard-delete consent submissions that have been soft-deleted for >90 days.
 * Also removes signature + PDF files from Supabase Storage.
 */
async function purgeSoftDeletedConsents() {
  const log = logger.child({ job: 'purge-soft-deleted-consents' })
  const supabase = getServiceRoleClient()

  // Find rows ready for hard deletion (soft_deleted_at < now() - 90 days)
  const { data: rows, error: fetchError } = await supabase
    .from('consent_form_submissions')
    .select('id, signature_path, guardian_signature_path, pdf_path')
    .eq('status', 'soft_deleted')
    .lt('soft_deleted_at', new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString())
    .limit(500)

  if (fetchError) {
    log.error({ err: fetchError }, 'failed to fetch soft-deleted submissions')
    return
  }

  if (!rows || rows.length === 0) {
    log.info('no soft-deleted submissions to hard-delete')
    return
  }

  // Remove storage objects
  const storagePaths: string[] = []
  for (const row of rows) {
    const r = row as {
      id: string
      signature_path: string | null
      guardian_signature_path: string | null
      pdf_path: string | null
    }
    if (r.signature_path) storagePaths.push(r.signature_path)
    if (r.guardian_signature_path) storagePaths.push(r.guardian_signature_path)
    if (r.pdf_path) storagePaths.push(r.pdf_path)
  }

  if (storagePaths.length > 0) {
    const { error: storageError } = await supabase.storage
      .from('consent-forms')
      .remove(storagePaths)
    if (storageError) {
      log.warn({ err: storageError }, 'some storage files could not be removed')
    }
  }

  // Hard-delete rows
  const ids = (rows as Array<{ id: string }>).map((r) => r.id)
  const { error: deleteError } = await supabase
    .from('consent_form_submissions')
    .delete()
    .in('id', ids)

  if (deleteError) {
    log.error({ err: deleteError }, 'hard-delete failed')
    return
  }

  log.info({ count: ids.length }, 'consent submissions hard-deleted with storage cleanup')
}

logger.info('cron worker started')

