'use client'

import ReactMarkdown from 'react-markdown'
import rehypeSanitize, { defaultSchema } from 'rehype-sanitize'
import type { ConsentSection, SectionAnswerValue } from '@/types/consent'
import { cn } from '@/lib/utils'

/**
 * Restricted rehype-sanitize schema — allows only safe inline/block elements.
 * No scripts, no iframes, no event handlers.
 */
const SANITIZE_SCHEMA = {
  ...defaultSchema,
  tagNames: ['p', 'strong', 'em', 'ul', 'ol', 'li', 'a', 'br'],
  attributes: {
    ...defaultSchema.attributes,
    a: ['href'],
  },
}

interface SectionRendererProps {
  section: ConsentSection
  /** Preview mode — renders static placeholder for interactive sections */
  isPreview?: boolean
  /** Current answer value (for interactive + submission view modes) */
  answer?: unknown
  /** Called when the user changes the answer (interactive mode only) */
  onAnswer?: (value: SectionAnswerValue) => void
  className?: string
}

export function SectionRenderer({
  section,
  isPreview = false,
  answer,
  onAnswer,
  className,
}: SectionRendererProps) {
  return (
    <div className={cn('space-y-2', className)}>
      {renderSection(section, isPreview, answer, onAnswer)}
    </div>
  )
}

function renderSection(
  section: ConsentSection,
  isPreview: boolean,
  answer: unknown,
  onAnswer?: (value: SectionAnswerValue) => void
) {
  switch (section.kind) {
    case 'heading': {
      const Tag = section.level === 1 ? 'h1' : section.level === 2 ? 'h2' : 'h3'
      const sizeClass =
        section.level === 1 ? 'text-2xl' : section.level === 2 ? 'text-xl' : 'text-lg'
      return (
        <Tag className={cn('font-semibold tracking-tight', sizeClass)}>
          {section.label}
        </Tag>
      )
    }

    case 'paragraph':
      return (
        <div className="prose prose-invert prose-sm max-w-none text-sm text-muted-foreground leading-relaxed">
          <ReactMarkdown rehypePlugins={[[rehypeSanitize, SANITIZE_SCHEMA]]}>
            {section.body}
          </ReactMarkdown>
        </div>
      )

    case 'checkbox': {
      const isChecked = answer === true
      return (
        <div className="space-y-2">
          {section.label && <p className="text-sm font-medium">{section.label}</p>}
          <div className="flex items-start gap-3">
            {isPreview ? (
              <div className="mt-0.5 h-4 w-4 shrink-0 rounded border border-border bg-muted" />
            ) : (
              <input
                type="checkbox"
                id={`section-${section.id}`}
                checked={isChecked}
                onChange={(e) => onAnswer?.(e.target.checked)}
                className="mt-0.5 h-4 w-4 shrink-0 rounded border-border cursor-pointer"
                aria-required={section.required}
              />
            )}
            <label
              htmlFor={isPreview ? undefined : `section-${section.id}`}
              className="prose prose-invert prose-sm max-w-none text-sm text-muted-foreground cursor-pointer"
            >
              <ReactMarkdown rehypePlugins={[[rehypeSanitize, SANITIZE_SCHEMA]]}>
                {section.body}
              </ReactMarkdown>
            </label>
          </div>
          {section.required && !isPreview && (
            <span className="text-xs text-muted-foreground">* Required</span>
          )}
        </div>
      )
    }

    case 'text_input': {
      const textValue = typeof answer === 'string' ? answer : ''
      return (
        <div className="space-y-1.5">
          <label className="text-sm font-medium" htmlFor={`section-${section.id}`}>
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </label>
          {isPreview ? (
            <div className="h-10 w-full rounded-md border border-border bg-muted/50 px-3 flex items-center">
              <span className="text-xs text-muted-foreground">
                {section.placeholder ?? 'Text input'}
              </span>
            </div>
          ) : (
            <input
              id={`section-${section.id}`}
              type="text"
              value={textValue}
              onChange={(e) => onAnswer?.(e.target.value)}
              placeholder={section.placeholder ?? ''}
              minLength={section.min_length}
              maxLength={section.max_length}
              required={section.required}
              className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            />
          )}
        </div>
      )
    }

    case 'date': {
      const dateValue = typeof answer === 'string' ? answer : ''
      return (
        <div className="space-y-1.5">
          <label className="text-sm font-medium" htmlFor={`section-${section.id}`}>
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </label>
          {isPreview ? (
            <div className="h-10 w-full rounded-md border border-border bg-muted/50 px-3 flex items-center">
              <span className="text-xs text-muted-foreground">Date picker</span>
            </div>
          ) : (
            <input
              id={`section-${section.id}`}
              type="date"
              value={dateValue}
              onChange={(e) => onAnswer?.(e.target.value)}
              required={section.required}
              className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            />
          )}
          {section.min_age && (
            <p className="text-xs text-muted-foreground">
              Must be {section.min_age}+ years old
            </p>
          )}
        </div>
      )
    }

    case 'dropdown': {
      const dropdownValue = typeof answer === 'string' ? answer : ''
      return (
        <div className="space-y-1.5">
          <label className="text-sm font-medium" htmlFor={`section-${section.id}`}>
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </label>
          {isPreview ? (
            <div className="h-10 w-full rounded-md border border-border bg-muted/50 px-3 flex items-center">
              <span className="text-xs text-muted-foreground">Select an option</span>
            </div>
          ) : (
            <select
              id={`section-${section.id}`}
              value={dropdownValue}
              onChange={(e) => onAnswer?.(e.target.value)}
              required={section.required}
              className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            >
              <option value="">Select…</option>
              {section.options.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          )}
        </div>
      )
    }

    case 'file_upload':
      return (
        <div className="space-y-1.5">
          <label className="text-sm font-medium" htmlFor={`section-${section.id}`}>
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </label>
          <div className="rounded-lg border border-dashed border-border bg-muted/30 px-6 py-8 text-center">
            {isPreview ? (
              <p className="text-xs text-muted-foreground">
                Upload file · Max {section.max_size_mb} MB
                {section.accept.length > 0 && ` · ${section.accept.join(', ')}`}
              </p>
            ) : (
              <label
                htmlFor={`section-${section.id}`}
                className="cursor-pointer text-xs text-primary underline underline-offset-4"
              >
                Choose file
                <input
                  id={`section-${section.id}`}
                  type="file"
                  accept={section.accept.join(',')}
                  className="sr-only"
                  onChange={(e) => {
                    const file = e.target.files?.[0]
                    if (!file) return
                    const reader = new FileReader()
                    reader.onload = () => onAnswer?.(reader.result as string)
                    reader.readAsDataURL(file)
                  }}
                />
              </label>
            )}
            {typeof answer === 'string' && answer.length > 0 && !isPreview && (
              <p className="mt-1 text-xs text-green-500">File selected</p>
            )}
          </div>
        </div>
      )

    case 'signature':
      return (
        <div className="space-y-1.5">
          <p className="text-sm font-medium">
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </p>
          {section.signer === 'guardian' && (
            <p className="text-xs text-muted-foreground">Guardian / parent signature</p>
          )}
          {isPreview || typeof answer === 'string' ? (
            typeof answer === 'string' && answer.length > 0 ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={answer}
                alt="Signature"
                className="max-h-20 w-auto rounded border border-border bg-white"
              />
            ) : (
              <div className="sig-pad-wrapper h-[120px] w-full flex items-center justify-center">
                <span className="text-xs text-muted-foreground">Signature area</span>
              </div>
            )
          ) : (
            <div className="sig-pad-wrapper h-[120px] w-full flex items-center justify-center">
              <span className="text-xs text-muted-foreground">
                Signature captured above
              </span>
            </div>
          )}
        </div>
      )

    case 'initials': {
      const initialsValue = typeof answer === 'string' ? answer : ''
      return (
        <div className="space-y-1.5">
          <p className="text-sm font-medium">
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </p>
          <div className="prose prose-invert prose-sm max-w-none text-sm text-muted-foreground">
            <ReactMarkdown rehypePlugins={[[rehypeSanitize, SANITIZE_SCHEMA]]}>
              {section.body}
            </ReactMarkdown>
          </div>
          {isPreview ? (
            <div className="h-10 w-32 rounded-md border border-border bg-muted/50 flex items-center justify-center">
              <span className="text-xs text-muted-foreground">Initials</span>
            </div>
          ) : (
            <input
              id={`section-${section.id}`}
              type="text"
              value={initialsValue}
              onChange={(e) => onAnswer?.(e.target.value)}
              placeholder="Your initials"
              maxLength={6}
              required={section.required}
              className="h-10 w-24 rounded-md border border-input bg-background px-3 text-center text-sm font-medium uppercase tracking-widest focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            />
          )}
        </div>
      )
    }

    case 'ink_disclosure': {
      const acknowledged = answer === true
      return (
        <div className="reach-block p-4 space-y-2">
          <p className="text-sm font-semibold text-foreground">
            {section.label}
            {section.required && <span className="ml-1 text-destructive">*</span>}
          </p>
          <div className="prose prose-invert prose-sm max-w-none text-sm text-muted-foreground">
            <ReactMarkdown rehypePlugins={[[rehypeSanitize, SANITIZE_SCHEMA]]}>
              {section.disclosure_text}
            </ReactMarkdown>
          </div>
          {!isPreview && (
            <label className="flex items-start gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={acknowledged}
                onChange={(e) => onAnswer?.(e.target.checked)}
                required={section.required}
                className="mt-0.5 h-4 w-4 shrink-0 rounded border-border"
              />
              <span className="text-sm text-foreground">
                I acknowledge this disclosure
              </span>
            </label>
          )}
        </div>
      )
    }

    case 'reach_batch_record':
      return (
        <div className="reach-block p-4 space-y-2">
          <p className="text-sm font-semibold text-foreground">{section.label}</p>
          <p className="text-xs text-muted-foreground italic">
            EU REACH ink batch records — completed by artist after session
          </p>
        </div>
      )

    default:
      return null
  }
}

